bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
for i in $(seq 1 24);do
  live="$(docker inspect -f '{{.Image}}' "$name" 2>/dev/null || true)"
  image="$(docker image inspect -f '{{.Id}}' create-videobot:native-sticker-148770 2>/dev/null || true)"
  if test -n "$image" && test "$live" = "$image" &&
     test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true &&
     docker logs --tail 150 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' &&
     docker logs --tail 150 "$name" 2>&1 | grep -q '^CREATOR_GATE_PUBLIC_RELEASE=CONNECTED$';then
    break
  fi
  sleep 5
done
live="$(docker inspect -f '{{.Image}}' "$name" 2>/dev/null || true)"
image="$(docker image inspect -f '{{.Id}}' create-videobot:native-sticker-148770 2>/dev/null || true)"
test -n "$image" && test "$live" = "$image" || { echo STK_NATIVE_CAPTION_IMAGE_NOT_READY; exit 81; }
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createPostgresStickerSales} from './src/stickers/pgStickerSales.mjs';
import {createPostgresStickerTopicPosts} from './src/stickers/pgStickerTopicPosts.mjs';
import {createStickerTopicPublisher} from './src/stickers/topicPublication.mjs';
import {createGateOwner} from './owner/gateOwner.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const e=process.env,pid='sp_76f23430d1c29ca355960a95';
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,
 database:e.VIDEOBOT_DB_NAME,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),
 max:2,connectionTimeoutMillis:5000});
const outbound=createCreatorTelegramFetch(globalThis.fetch);
try{
 const sql=await pool.query("SELECT p.product_id,p.seller_user_id,p.price_stars,p.title,p.status AS product_status,t.status AS topic_status,t.chat_id,t.message_thread_id,t.telegram_message_id FROM videobot_sticker_products p JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",[pid]);
 if(sql.rowCount!==1)throw Error('STK_IMAGE_EXISTING_POST_NOT_FOUND');
 const row=sql.rows[0];
 if(row.product_status!=='published'||row.topic_status!=='sent'||
    Number(row.price_stars)!==50||Number(row.chat_id)!==-1002373696859||
    Number(row.message_thread_id)!==4640||
    !Number.isSafeInteger(Number(row.telegram_message_id))||
    Number(row.telegram_message_id)<=0)
   throw Error('STK_IMAGE_ORIGINAL_POST_RECEIPT_INVALID');
 const pin=JSON.parse(readFileSync('/var/lib/videobot/sticker-entry/group2373696859_thread4640.json','utf8'));
 if(pin.status!=='pinned_ack'||Number(pin.message_id)===Number(row.telegram_message_id))
   throw Error('STK_IMAGE_DO_NOT_TOUCH_PINNED_ENTRY');
 const seller=Number(row.seller_user_id);
 if(!Number.isSafeInteger(seller)||seller<=0)throw Error('STK_IMAGE_SELLER_INVALID');
 const token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
 const transport=createTelegramBotApi({token,fetchImpl:outbound.fetch,timeoutMs:25000});
 let captionEdits=0,buttonRemovals=0;
 const api=async(method,args)=>{
   if(method==='editMessageCaption'){
     if(args.chat_id!==-1002373696859||
        Number(args.message_id)!==Number(row.telegram_message_id)||
        args.caption!=='🎨 '+row.title||
        Object.hasOwn(args,'reply_markup'))
       throw Error('STK_IMAGE_UNEXPECTED_CAPTION_MUTATION');
     captionEdits++;
   }else if(method==='editMessageReplyMarkup'){
     if(args.chat_id!==-1002373696859||
        Number(args.message_id)!==Number(row.telegram_message_id)||
        Object.hasOwn(args,'reply_markup'))
       throw Error('STK_IMAGE_UNEXPECTED_MARKUP_MUTATION');
     buttonRemovals++;
   }else if(!['getMe','getChat','getChatMember'].includes(method))
     throw Error('STK_IMAGE_UNEXPECTED_TELEGRAM_OPERATION');
   return transport(method,args);
 };
 const owner=await createGateOwner({telegramApi:api,pool});
 const route=await owner.getVerifiedStickerTopic();
 if(route.chatId!==-1002373696859||route.threadId!==4640)
   throw Error('STK_IMAGE_ROUTE_CHANGED');
 const publisher=createStickerTopicPublisher({
   telegramApi:api,getVerifiedStickerTopic:owner.getVerifiedStickerTopic,
   verifyMembership:owner.verifyMembership,
   verifyReview:owner.verifyStickerReview,
   verifyRelease:owner.verifyRelease,
   receiptStore:createPostgresStickerTopicPosts(pool),
   salesStore:createPostgresStickerSales(pool),
   createPaidCover:async()=>{throw Error('STK_IMAGE_NO_REPUBLICATION');}
 });
 const result=await publisher.edit({sellerId:seller,productId:pid,description:''});
 if(result.verified!==true||captionEdits!==1||buttonRemovals!==1)
   throw Error('STK_IMAGE_EXISTING_CAPTION_NOT_EDITED');
 const after=await pool.query("SELECT status,display_text,telegram_message_id FROM videobot_sticker_topic_posts WHERE product_id=$1",[pid]);
 if(after.rowCount!==1||after.rows[0].status!=='sent'||
    Number(after.rows[0].telegram_message_id)!==Number(row.telegram_message_id)||
    after.rows[0].display_text!=='🎨 '+row.title)
   throw Error('STK_IMAGE_CAPTION_DB_READBACK_INVALID');
 console.log('STK_NATIVE_EXISTING_IMAGE_CAPTION_MINIMAL=PASS');
 console.log('STK_NATIVE_EXTRA_BUTTON_REMOVED=PASS');
 console.log('STK_NATIVE_PAYWALL_MESSAGE_UNCHANGED=PASS');
 console.log('STK_NATIVE_EXISTING_MESSAGE_ID='+Number(row.telegram_message_id));
}finally{await outbound.close();await pool.end();}
NODE
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 82
echo STK_NATIVE_IMAGE_ONLY_BOT_HEALTH=PASS
